<?php
session_start();
require_once __DIR__ . '/config.php';
if (empty($_SESSION['organization_id'])) { header('Location: /login.php'); exit; }
$orgId=(int)$_SESSION['organization_id'];
function ah($v): string { return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8'); }
function istDate(?string $v): string { if(!$v)return '—'; try{return (new DateTime($v,new DateTimeZone('Asia/Kolkata')))->format('d M Y, h:i A').' IST';}catch(Throwable $e){return '—';} }
if(empty($_SESSION['attendance_csrf']))$_SESSION['attendance_csrf']=bin2hex(random_bytes(32));
$message='';$messageType='';$lastCheckin=null;$codeValue='';$selectedEvent=(int)($_POST['event_id']??$_GET['event_id']??0);
try{
  $es=$pdo->prepare('SELECT id,event_name,event_date FROM events WHERE organization_id=:org ORDER BY event_date DESC,id DESC');$es->execute([':org'=>$orgId]);$events=$es->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){error_log('Attendance events: '.$e->getMessage());http_response_code(500);exit('Unable to load your events.');}
$validIds=array_map(fn($r)=>(int)$r['id'],$events);if($selectedEvent && !in_array($selectedEvent,$validIds,true))$selectedEvent=0;
if($_SERVER['REQUEST_METHOD']==='POST'){
  $codeValue=trim((string)($_POST['registration_code']??''));$csrf=(string)($_POST['csrf_token']??'');
  if(!hash_equals($_SESSION['attendance_csrf'],$csrf)){$message='Your session expired. Refresh the page and try again.';$messageType='error';}
  else {
    // Accept either an EF registration number or a ticket URL decoded from the QR.
    if(filter_var($codeValue,FILTER_VALIDATE_URL)){$parts=parse_url($codeValue);parse_str((string)($parts['query']??''),$qp);$codeValue=(string)($qp['code']??'');}
    $codeValue=strtoupper(trim($codeValue));
    if(!preg_match('/^EF-[A-F0-9]{12}$/',$codeValue)){$message='Enter a valid registration number or scan the participant QR code.';$messageType='error';}
    else {
      try{
        $q=$pdo->prepare("SELECT r.id,r.event_id,r.organization_id,r.participant_name,r.email,r.phone,r.race_distance,r.registration_code,r.status,r.check_in_at,e.event_name,e.event_date,e.venue FROM event_registrations r INNER JOIN events e ON e.id=r.event_id WHERE r.registration_code=:code AND r.organization_id=:org LIMIT 1");
        $q->execute([':code'=>$codeValue,':org'=>$orgId]);$participant=$q->fetch(PDO::FETCH_ASSOC);
        if(!$participant){$message='Registration was not found in your organization.';$messageType='error';}
        elseif($selectedEvent>0&&(int)$participant['event_id']!==$selectedEvent){$message='This registration belongs to a different event. Select the correct event and scan again.';$messageType='error';}
        elseif((string)$participant['status']==='cancelled'){$message='This registration is cancelled. Attendance was not recorded.';$messageType='error';}
        elseif(!empty($participant['check_in_at'])){$lastCheckin=$participant;$message='Already checked in. This participant is marked PRESENT.';$messageType='success';}
        else{
          $istNow=(new DateTime('now',new DateTimeZone('Asia/Kolkata')))->format('Y-m-d H:i:s');
          $u=$pdo->prepare('UPDATE event_registrations SET check_in_at=:check_in_at WHERE id=:id AND check_in_at IS NULL');
          $u->execute([':check_in_at'=>$istNow,':id'=>(int)$participant['id']]);
          $q->execute([':code'=>$codeValue,':org'=>$orgId]);$lastCheckin=$q->fetch(PDO::FETCH_ASSOC);
          if($lastCheckin && !empty($lastCheckin['check_in_at'])){$message='Check-in successful. Participant marked PRESENT.';$messageType='success';}
          else{$message='Unable to confirm this check-in. Please search by registration number again.';$messageType='error';}
        }
      }catch(Throwable $e){error_log('Attendance check-in error: '.$e->getMessage());$message='Unable to record attendance. Please confirm the database update has been completed.';$messageType='error';}
    }
  }
}
try{
 $params=[':org'=>$orgId];$where='r.organization_id=:org';
 if($selectedEvent>0){$where.=' AND r.event_id=:event_id';$params[':event_id']=$selectedEvent;}
 $countStmt=$pdo->prepare("SELECT COUNT(*) FROM event_registrations r WHERE $where AND r.check_in_at IS NOT NULL");$countStmt->execute($params);$presentCount=(int)$countStmt->fetchColumn();
 $listStmt=$pdo->prepare("SELECT r.participant_name,r.phone,r.race_distance,r.registration_code,r.check_in_at,r.status,e.event_name FROM event_registrations r INNER JOIN events e ON e.id=r.event_id WHERE $where ORDER BY (r.check_in_at IS NOT NULL) DESC,r.check_in_at DESC,r.id DESC LIMIT 100");$listStmt->execute($params);$recent=$listStmt->fetchAll(PDO::FETCH_ASSOC);
}catch(Throwable $e){error_log('Attendance list error: '.$e->getMessage());$presentCount=0;$recent=[];if(!$message){$message='Attendance table needs a database update before use.';$messageType='error';}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Attendance Check-in | EventFlow</title><style>
:root{--p:#635bff;--ink:#182039;--muted:#727b91;--line:#e8ebf3;--bg:#f6f7fc;--green:#138052;--red:#b53043}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif;font-size:14px}a{text-decoration:none;color:inherit}.top{min-height:70px;background:#fff;border-bottom:1px solid var(--line);padding:0 max(4%,calc((100% - 1180px)/2));display:flex;align-items:center;justify-content:space-between;gap:12px}.brand{font-size:22px;font-weight:900}.brand span{color:var(--p)}.nav{display:flex;gap:14px;color:var(--p);font-size:12px;font-weight:800}.wrap{width:min(1180px,92%);margin:28px auto 45px}.eyebrow{color:var(--p);font-size:10px;letter-spacing:1.4px;font-weight:900;text-transform:uppercase}h1{font-size:clamp(27px,4vw,36px);letter-spacing:-1px;margin:8px 0}.lead{margin:0;color:var(--muted);font-size:13px;line-height:1.7}.topgrid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(270px,.75fr);gap:16px;margin-top:22px}.panel{background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;min-width:0;box-shadow:0 10px 35px #18203908}.panel h2{margin:0 0 7px;font-size:17px}.muted{color:var(--muted);font-size:12px;line-height:1.65}.field{margin:15px 0}label{display:block;font-size:12px;font-weight:800;margin-bottom:7px}input,select{width:100%;min-height:47px;border:1px solid #dfe3ed;border-radius:11px;background:#fbfcff;padding:11px 13px;font:inherit;font-size:13px;outline:none}input:focus,select:focus{border-color:var(--p);box-shadow:0 0 0 3px #635bff16}.btn{border:0;min-height:45px;padding:0 16px;border-radius:11px;background:linear-gradient(110deg,#6e63ff,#5046e4);color:#fff;font-weight:850;font-size:12px;cursor:pointer;display:inline-flex;align-items:center;justify-content:center}.btn.secondary{background:#fff;color:var(--ink);border:1px solid var(--line)}.btnrow{display:flex;gap:9px;flex-wrap:wrap}.scanner-box{display:none;margin-top:15px;padding:12px;border:1px dashed #b9b4ff;border-radius:14px;background:#fafaff}.scanner-box.show{display:block}#qr-reader{width:100%;max-width:480px;margin:auto}#qr-reader video{border-radius:12px}.message{margin:18px 0 0;padding:14px 15px;border-radius:12px;font-size:12px;line-height:1.7}.message.success{background:#e8f8ef;border:1px solid #cdebd9;color:#126b47}.message.error{background:#fff0f2;border:1px solid #f3d3d9;color:#a52c40}.result{margin-top:13px;border:1px solid #bce8ce;background:#f3fcf6;border-radius:14px;padding:15px}.result h3{margin:0 0 11px;color:#126b47}.result-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.result small{display:block;color:#6e8178;font-size:9px;letter-spacing:.7px;font-weight:900;text-transform:uppercase;margin-bottom:4px}.result strong{font-size:12px;overflow-wrap:anywhere}.metric{display:flex;align-items:center;justify-content:space-between;background:#f5f4ff;border:1px solid #e5e1ff;border-radius:14px;padding:15px 16px;margin-top:15px}.metric span{color:#5c6380;font-size:12px;font-weight:800}.metric strong{font-size:27px;color:var(--p)}.table-panel{margin-top:20px;background:#fff;border:1px solid var(--line);border-radius:18px;overflow:hidden}.tablehead{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:18px 20px;border-bottom:1px solid var(--line)}.tablehead h2{margin:0;font-size:16px}.tablewrap{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:740px}th,td{text-align:left;padding:13px 15px;border-bottom:1px solid #eff1f6;font-size:11px;vertical-align:top}th{font-size:9px;letter-spacing:.8px;text-transform:uppercase;color:#818ba0;background:#fbfcff}td strong{font-size:12px;display:block}td small{color:var(--muted);display:block;margin-top:4px}.badge{display:inline-flex;border-radius:7px;padding:6px 8px;background:#e7f8ef;color:#13794b;font-size:9px;font-weight:900}.badge.out{background:#f1f3f7;color:#707b8f}.empty{padding:30px;text-align:center;color:var(--muted);font-size:12px}.foot{text-align:center;color:#8b94a7;font-size:10px;margin-top:25px}@media(max-width:850px){.topgrid{grid-template-columns:1fr}}@media(max-width:520px){.top{min-height:62px;padding:0 4%}.brand{font-size:18px}.nav{gap:9px;font-size:10px}.wrap{margin-top:20px}.panel{padding:16px}.btnrow .btn{flex:1}.result-grid{grid-template-columns:1fr 1fr}.tablehead{padding:15px}.tablehead span{display:none}}
</style></head><body><header class="top"><a class="brand" href="/dashboard.php">Event<span>Flow</span></a><nav class="nav"><a href="/dashboard.php">Dashboard</a><a href="/participants.php">Participants</a></nav></header><main class="wrap"><div class="eyebrow">Race-day operations</div><h1>Attendance check-in</h1><p class="lead">Scan a participant's QR pass or enter their unique registration number. A successful check-in marks them PRESENT and records the time in India Standard Time (IST).</p>
<?php if($message):?><div class="message <?=ah($messageType)?>"><?=ah($message)?></div><?php endif;?>
<?php if($lastCheckin):?><section class="result"><h3>✓ Participant details</h3><div class="result-grid"><div><small>Name</small><strong><?=ah($lastCheckin['participant_name'])?></strong></div><div><small>Event</small><strong><?=ah($lastCheckin['event_name'])?></strong></div><div><small>Mobile</small><strong><?=ah($lastCheckin['phone'])?></strong></div><div><small>Race category</small><strong><?=ah($lastCheckin['race_distance'])?></strong></div><div><small>Registration number</small><strong><?=ah($lastCheckin['registration_code'])?></strong></div><div><small>Attendance</small><strong>PRESENT</strong></div><div><small>Check-in time</small><strong><?=ah(istDate((string)$lastCheckin['check_in_at']))?></strong></div></div><p class="muted">Participant has been checked in for this event.</p></section><?php endif;?>
<div class="topgrid"><section class="panel"><h2>Scan QR or enter registration number</h2><p class="muted">Use the camera on a phone/tablet, or type the code printed on the participant's pass (example: EF-1A2B3C4D5E6F).</p><form id="checkin-form" method="post"><input type="hidden" name="csrf_token" value="<?=ah($_SESSION['attendance_csrf'])?>"><div class="field"><label for="event_id">Event</label><select id="event_id" name="event_id"><option value="0">All my events</option><?php foreach($events as $ev):?><option value="<?= (int)$ev['id']?>" <?= $selectedEvent===(int)$ev['id']?'selected':''?>><?=ah($ev['event_name'])?></option><?php endforeach;?></select></div><div class="field"><label for="registration_code">Unique registration number</label><input id="registration_code" name="registration_code" autocomplete="off" placeholder="EF-1A2B3C4D5E6F" value="<?=ah($codeValue)?>" required></div><div class="btnrow"><button class="btn" type="submit">Confirm Check-in</button><button class="btn secondary" type="button" id="start-scan">Scan QR with camera</button></div></form><div id="scanner-box" class="scanner-box"><div id="qr-reader"></div><button class="btn secondary" id="stop-scan" type="button" style="margin-top:10px">Stop camera</button><p class="muted">Allow camera access if your browser asks. On mobile, HTTPS is required for camera scanning.</p></div></section><aside class="panel"><h2>Today's check-in overview</h2><p class="muted">Checked-in participants for the selected event or all your events.</p><div class="metric"><span>Marked PRESENT</span><strong><?=number_format($presentCount)?></strong></div><p class="muted">If a participant has already checked in, scanning the pass again will show the original check-in time instead of creating a duplicate.</p></aside></div>
<section class="table-panel"><div class="tablehead"><h2>Recent participants</h2><span class="muted">Latest 100 registrations</span></div><?php if(!$recent):?><div class="empty">No participant registrations have been found for this selection.</div><?php else:?><div class="tablewrap"><table><thead><tr><th>Participant</th><th>Event</th><th>Mobile</th><th>Registration No.</th><th>Attendance</th><th>Check-in time (IST)</th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><strong><?=ah($r['participant_name'])?></strong><small><?=ah($r['race_distance'])?></small></td><td><?=ah($r['event_name'])?></td><td><?=ah($r['phone'])?></td><td><strong><?=ah($r['registration_code'])?></strong></td><td><?=!empty($r['check_in_at'])?'<span class="badge">PRESENT</span>':'<span class="badge out">Not checked in</span>'?></td><td><?=!empty($r['check_in_at'])?ah(istDate((string)$r['check_in_at'])):'—'?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><div class="foot">EventFlow · Private organization attendance workspace</div></main>
<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script>
const scanBtn=document.getElementById('start-scan'),stopBtn=document.getElementById('stop-scan'),box=document.getElementById('scanner-box'),input=document.getElementById('registration_code'),form=document.getElementById('checkin-form');let scanner=null,locked=false;
function codeFromScan(decoded){try{const u=new URL(decoded);const c=u.searchParams.get('code');if(c)return c;}catch(e){}const match=String(decoded).toUpperCase().match(/EF-[A-F0-9]{12}/);return match?match[0]:String(decoded).trim();}
scanBtn?.addEventListener('click',async()=>{if(!window.Html5Qrcode){alert('QR scanning library could not load. Please enter the registration number manually.');return;}box.classList.add('show');scanner=new Html5Qrcode('qr-reader');try{locked=false;await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230}},async text=>{if(locked)return;locked=true;input.value=codeFromScan(text);try{await scanner.stop();}catch(e){}form.requestSubmit();},()=>{});}catch(e){box.classList.remove('show');alert('Could not start camera. Allow camera access or enter the registration number manually.');}});
stopBtn?.addEventListener('click',async()=>{if(scanner){try{await scanner.stop();}catch(e){}try{scanner.clear();}catch(e){}}box.classList.remove('show');});
</script></body></html>